/// <summary>
/// AVA/WEN/2025/01/21  AVA_012939_CreateNewCompanyProduct
/// </summary>
class AVACreateNewCompanyProdUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField dlgCompany, dlgItemId;
    AVACreateNewCompanyProdContract contract;

}

Method.Source:
public void postBuild()
{
    super();
    contract = this.dataContractObject();

    dlgCompany = this.bindInfo().getDialogField(contract, methodStr(AVACreateNewCompanyProdContract, parmCompany));  
    dlgCompany.fieldControl().mandatory(true);

    dlgItemId = this.bindInfo().getDialogField(contract, methodStr(AVACreateNewCompanyProdContract, parmItemId));

}

public void postRun()
{
    super();
    dlgCompany.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(AVACreateNewCompanyProdUIBuilder, modifiedCompany), this);
}

/// <summary>
/// AVA/WEN/2025/01/21  AVA_012939_CreateNewCompanyProduct
/// </summary>
/// <param name = "_dialogField">FormStringControl</param>
/// <returns>booolean</returns>
public boolean modifiedCompany(FormStringControl _dialogField)
{
    DataAreaId company;
    RefRecId product;
    ItemId itemId;
    EcoResProduct ecoResProduct;

    company = _dialogField.valueStr();
    product = contract.parmProduct();
    ecoResProduct = ecoResProduct::find(product);
    InventTable inventTable;

    inventTable = inventTable::findByProductInCompany(product, company);
    if (inventTable)
    {
        Error("@NDX:NXACompanyProdExists");
        dlgItemId.allowEdit(false);
        dlgItemId.value('');
    }
    else
    {
        itemId = NDXItemIdHandler::constructFromDataAreaId(company).checkItemId(ecoResProduct.productNumber());
        dlgItemId.allowEdit(true);
        dlgItemId.value(itemId);
    }

    return true;
}
